#!/usr/bin/env python3
"""
adjust_pdf_field.py

Utility for modifying PDF form fields. Given a PDF path, a form-field name,
and a numeric adjustment, this script reads the current value of the field;
if the value looks like a date, the year component is shifted by the
adjustment amount and the field is rewritten. The modified PDF is saved
to a new file (or overwrites the original if --in-place is given).

Usage:
    python adjust_pdf_field.py <pdf_path> <field_name> <adjustment> [-o OUTPUT] [--in-place]

Example:
    python adjust_pdf_field.py form.pdf "BirthDate" 1
        -> shifts the year of the BirthDate field forward by 1.
"""

from __future__ import annotations

import argparse
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Optional, Tuple

try:
    from pypdf import PdfReader, PdfWriter
    from pypdf.generic import NameObject, TextStringObject
except ImportError:  # pragma: no cover - fallback for older installs
    try:
        from PyPDF2 import PdfReader, PdfWriter  # type: ignore
        from PyPDF2.generic import NameObject, TextStringObject  # type: ignore
    except ImportError as exc:
        sys.stderr.write(
            "Error: this script requires the 'pypdf' (or 'PyPDF2') package.\n"
            "Install it with: pip install pypdf\n"
        )
        raise SystemExit(1) from exc


# Common date patterns we recognise. Each entry maps a regex to the
# strptime/strftime format string that produced it.
DATE_FORMATS: Tuple[Tuple[str, str], ...] = (
    (r"^\d{4}-\d{2}-\d{2}$", "%Y-%m-%d"),
    (r"^\d{2}/\d{2}/\d{4}$", "%m/%d/%Y"),
    (r"^\d{2}-\d{2}-\d{4}$", "%m-%d-%Y"),
    (r"^\d{4}/\d{2}/\d{2}$", "%Y/%m/%d"),
    (r"^\d{2}\.\d{2}\.\d{4}$", "%d.%m.%Y"),
    (r"^\d{1,2} [A-Za-z]+ \d{4}$", "%d %B %Y"),
    (r"^[A-Za-z]+ \d{1,2}, \d{4}$", "%B %d, %Y"),
)


def looks_like_date(value: str) -> Optional[Tuple[datetime, str]]:
    """Return (datetime, format) if `value` matches a known date pattern."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    for pattern, fmt in DATE_FORMATS:
        if re.match(pattern, value):
            try:
                return datetime.strptime(value, fmt), fmt
            except ValueError:
                continue
    return None


def shift_year(value: str, adjustment: int) -> str:
    """If `value` is a date, add `adjustment` to its year and return the
    re-formatted string. Otherwise return the original value unchanged."""
    parsed = looks_like_date(value)
    if parsed is None:
        return value
    dt, fmt = parsed
    try:
        new_dt = dt.replace(year=dt.year + adjustment)
    except ValueError:
        # Handles edge case of Feb 29 on a non-leap target year.
        new_dt = dt.replace(month=2, day=28, year=dt.year + adjustment)
    return new_dt.strftime(fmt)


def read_field(reader: PdfReader, field_name: str) -> Optional[str]:
    """Return the current value of `field_name`, or None if not present."""
    fields = reader.get_fields() or {}
    if field_name not in fields:
        return None
    field = fields[field_name]
    # `field.value` is the most reliable accessor across pypdf versions.
    value = getattr(field, "value", None)
    if value is None and isinstance(field, dict):
        value = field.get("/V")
    return None if value is None else str(value)


def update_field(
    reader: PdfReader, writer: PdfWriter, field_name: str, new_value: str
) -> None:
    """Write `new_value` into `field_name` for every page that contains it."""
    # Copy pages over, then update form values on each page.
    for page in reader.pages:
        writer.add_page(page)

    # Preserve AcroForm and ensure field appearances will be regenerated
    # by viewers that honour /NeedAppearances.
    if "/AcroForm" in reader.trailer["/Root"]:
        writer._root_object.update(
            {NameObject("/AcroForm"): reader.trailer["/Root"]["/AcroForm"]}
        )
        writer._root_object["/AcroForm"].update(
            {NameObject("/NeedAppearances"): TextStringObject("true")}  # type: ignore[arg-type]
        )

    for page in writer.pages:
        if page.get("/Annots"):
            writer.update_page_form_field_values(page, {field_name: new_value})


def adjust_pdf_field(
    pdf_path: Path, field_name: str, adjustment: int, output_path: Path
) -> Tuple[str, str]:
    """Perform the adjustment and write the result to `output_path`.

    Returns a tuple of (old_value, new_value).
    """
    reader = PdfReader(str(pdf_path))
    current = read_field(reader, field_name)
    if current is None:
        raise KeyError(f"Field {field_name!r} not found in {pdf_path}")

    new_value = shift_year(current, adjustment)

    writer = PdfWriter()
    update_field(reader, writer, field_name, new_value)

    with open(output_path, "wb") as fh:
        writer.write(fh)

    return current, new_value


def parse_args(argv: Optional[list[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Adjust a PDF form field; if it's a date, shift the year."
    )
    parser.add_argument("pdf_path", type=Path, help="Path to the source PDF.")
    parser.add_argument("field_name", help="Name of the form field to modify.")
    parser.add_argument(
        "adjustment",
        type=int,
        help="Numeric adjustment (added to the year if the field is a date).",
    )
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        default=None,
        help="Output PDF path (defaults to <pdf>_adjusted.pdf).",
    )
    parser.add_argument(
        "--in-place",
        action="store_true",
        help="Overwrite the source PDF instead of writing a new file.",
    )
    return parser.parse_args(argv)


def main(argv: Optional[list[str]] = None) -> int:
    args = parse_args(argv)

    if not args.pdf_path.is_file():
        sys.stderr.write(f"Error: {args.pdf_path} is not a file.\n")
        return 2

    if args.in_place:
        output_path = args.pdf_path
    elif args.output is not None:
        output_path = args.output
    else:
        output_path = args.pdf_path.with_name(
            f"{args.pdf_path.stem}_adjusted{args.pdf_path.suffix}"
        )

    try:
        old, new = adjust_pdf_field(
            args.pdf_path, args.field_name, args.adjustment, output_path
        )
    except KeyError as exc:
        sys.stderr.write(f"Error: {exc}\n")
        return 1

    print(f"Field {args.field_name!r}: {old!r} -> {new!r}")
    print(f"Saved to {output_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
